import { describe, it } from "vitest";

describe("Game of Life -- nextGeneration", () => {
  // Output is treated as an unordered set of cells: the specification defines no
  // ordering contract, so every assertion compares order-insensitively.
  it.todo("returns no living cells for an empty grid -- [] -> []");

  it.todo(
    "kills a single living cell with 0 live neighbors (underpopulation) -- [[0,0]] -> []",
  );

  it.todo(
    "kills both cells of a live pair, each having 1 live neighbor (underpopulation) -- [[0,0],[1,0]] -> []",
  );

  it.todo(
    "keeps a living cell with exactly 2 live neighbors alive (survival) -- centre of [[0,0],[1,0],[2,0]] stays alive",
  );

  it.todo(
    "keeps a living cell with exactly 3 live neighbors alive (survival) -- every cell of the 2x2 block [[0,0],[1,0],[0,1],[1,1]] survives",
  );

  it.todo(
    "kills a living cell with more than 3 live neighbors (overpopulation) -- centre of [[0,0],[1,0],[-1,0],[0,1],[0,-1]] dies",
  );

  it.todo(
    "brings a dead cell with exactly 3 live neighbors to life (reproduction) -- [[0,0],[1,0],[0,1]] gives birth at [1,1]",
  );

  it.todo(
    "leaves a dead cell with exactly 2 live neighbors dead (no reproduction) -- [[0,0],[1,0]] gives no birth",
  );

  it.todo(
    "counts only the eight surrounding cells as neighbors -- a cell two steps away is not a neighbor",
  );

  it.todo(
    "handles negative coordinates -- blinker [[-1,-1],[-1,0],[-1,1]] rotates about [-1,0]",
  );

  it.todo(
    "evolves the blinker oscillator through a half period -- [[0,0],[1,0],[2,0]] -> [[1,-1],[1,0],[1,1]]",
  );

  it.todo(
    "returns the block still life unchanged -- [[0,0],[1,0],[0,1],[1,1]] -> same four cells",
  );

  it.todo(
    "evolves the glider by one generation -- [[1,0],[2,1],[0,2],[1,2],[2,2]] -> [[0,1],[2,1],[1,2],[2,2],[1,3]]",
  );
});

