export type Cell = [number, number]; // [x, y]

const SURVIVING_NEIGHBOUR_COUNT = 2;

const isNeighbour = ([x, y]: Cell, [otherX, otherY]: Cell): boolean =>
  !(x === otherX && y === otherY) &&
  Math.abs(x - otherX) <= 1 &&
  Math.abs(y - otherY) <= 1;

const countLiveNeighbours = (cell: Cell, cells: Cell[]): number =>
  cells.filter((other) => isNeighbour(cell, other)).length;

export function nextGeneration(cells: Cell[]): Cell[] {
  return cells.filter(
    (cell) => countLiveNeighbours(cell, cells) === SURVIVING_NEIGHBOUR_COUNT,
  );
}

